// moy_path: filled paths and the outline faces, anti-aliased, at any size.
//
// A path is polygons in 26.6 fixed point (1/64 px) in the target's
// coordinates before the camera; it fills by its coverage (an edge's area,
// accumulated a row at a time and summed across, as font-rs does), its
// winding counted to one: a contour inside another and turning the other
// way is a hole. Integer throughout, so every tier draws the same pixels.
//
// The outline faces are the shell's sans, sans bold and mono as TrueType
// outlines (moy_path_faces.h, generated by tools/make_outline_faces.py):
// a story's text at any size (docs/media/look_2026-10/APPS_RESTYLE.md, "The
// document"). A face draws one glyph a byte: UTF-8 is decoded, a codepoint
// in Latin-1 draws at its value and any other as `?`. Sizes are the em in
// 26.6 pixels; widths answer in 26.6.
//
// Colours are wire words, as moy_shape's; a partly covered pixel blends
// into what is there, in the byte order moy_shape_wire_swapped set.

#ifndef MOY_PATH_H
#define MOY_PATH_H

#include <stddef.h>
#include <stdint.h>

enum { MOY_PATH_SANS = 0, MOY_PATH_SANS_BOLD = 1, MOY_PATH_MONO = 2, MOY_PATH_FACES = 3 };

#define MOY_PATH_SIZE_MAX (512 * 64)    // the largest em a face draws at, 26.6

typedef struct {
    uint16_t adv, pt, npt, end;
    uint8_t nend;
} moy_path_glyph_t;

typedef struct {
    uint8_t a, b;
    int16_t dx;
} moy_path_kern_t;

typedef struct {
    int16_t upm, ascent, descent;
    const moy_path_glyph_t *glyphs;     // 224 records, bytes 0x20..0xFF
    const int16_t *pts;
    const uint16_t *ends;
    const moy_path_kern_t *kerns;
    uint16_t nkern;
} moy_path_face_t;

// Fill the path: `npts` points (x, y pairs, 26.6) in contours ending at
// `ends` (one past each contour's last point; the last end is npts) in
// colour `col`, into an RGB565 buffer `dw` pixels wide holding `cap`
// pixels, camera (cam_x, cam_y) and clip (cx0, cy0)-(cx1, cy1), exclusive.
// The pixels it touched, or -1 for a path it refuses (an end out of order,
// out of memory).
int mg_path_fill(uint16_t *dst, size_t cap, int dw, const int32_t *pts, int npts,
                 const int32_t *ends, int nends, int col, int cam_x, int cam_y,
                 int cx0, int cy0, int cx1, int cy1);

// Draw `s` (n bytes, UTF-8) in face `face` at em `size` (26.6) with its
// baseline's left end at (x, y), 26.6, as mg_path_fill places and blends.
// The advance in 26.6, or -1 for an unknown face or size.
int mg_path_text(uint16_t *dst, size_t cap, int dw, int face, int size, int x, int y,
                 const uint8_t *s, size_t n, int col, int cam_x, int cam_y,
                 int cx0, int cy0, int cx1, int cy1);

// The advance `s` takes in face `face` at em `size`, 26.6 (kerning
// included); -1 for an unknown face or size.
int moy_path_width(int face, int size, const uint8_t *s, size_t n);

// The face's em, ascent and descent (below the baseline, negative) in font
// units: 0 for an unknown face.
int moy_path_metrics(int face, int out[3]);

// The byte order blends read and write in (moy_shape_wire_swapped calls it).
void moy_path_wire_swapped(int swapped);

#endif
